'Amount_Paid' => 'Сплачена сума',
'Payment_Amounts_Help' => 'Сплачена сума погашає баланс і зменшує борг. Отримана сума — це передана готівка: вона використовується лише для розрахунку решти та не змінює борг.',
'Show_Tax_Desc' => 'Податок, застосований до всього продажу під час оформлення, друкується окремим рядком «Податок на замовлення» в підсумках.',
'Show_Items_Tax_Desc' => 'Сума власних податків кожного товару, друкується рядком «Загальний податок на позиції». Якщо увімкнено, проміжний підсумок показується без цих податків.',
'Show_Discount_Desc' => 'Знижка, застосована до всього продажу (включно зі знижкою за бали), друкується окремим рядком у підсумках.',
