'Wallet_Payment_Method_Missing' => 'Відсутній спосіб оплати «Гаманець»',
'Wallet_Payment_Method_Missing_Help' => 'Не знайдено способу оплати з точною назвою "Wallet". Оплата гаманцем у POS зіставляється за цією назвою, тож клієнти не зможуть платити гаманцем, доки ви не додасте тут спосіб оплати з назвою "Wallet":',
'Show_Previous_Dues_Line' => 'Показувати рядок попередніх боргів',
'Show_Previous_Dues_Line_Desc' => 'Баланс, який клієнт заборгував до цього продажу. Друкується, лише якщо він більший за нуль.',
'Show_Net_Balance_Line' => 'Показувати рядок чистого балансу',
'Show_Net_Balance_Line_Desc' => 'Попередні борги плюс несплачена сума за цим продажем. Друкується, лише якщо попередні борги більші за нуль.',
'QZ_Tray_Printer' => 'QZ Tray (принтер на цьому комп’ютері)',
'QZ_Printer_Name_Hint' => 'Назва принтера, як вона відображається на комп’ютері з QZ Tray. Залиште порожнім, щоб використовувати принтер за замовчуванням цього комп’ютера. Натисніть ⟳, щоб виявити принтери.',
'QZ_Not_Running' => 'QZ Tray не запущено на цьому комп’ютері. Встановіть його з qz.io, тримайте запущеним і дозвольте цей вебсайт, коли QZ запитає.',
'Detect_Printers' => 'Виявити принтери',
'QZ_Download_Cert' => 'Завантажити сертифікат (override.crt)',
'QZ_Setup_Title' => 'Як налаштувати друк через QZ Tray (один раз на кожному комп’ютері, що друкує етикетки)',
'QZ_Step_Install' => '1. Встановіть QZ Tray на цей комп’ютер — завантажте безкоштовно з qz.io, запустіть і залиште працювати (він знаходиться в системному треї Windows або в рядку меню macOS).',
'QZ_Step_Connect' => '2. Підключіть принтер етикеток через USB і переконайтеся, що його встановлено в операційній системі (Windows: Параметри > Принтери та сканери — macOS: Системні параметри > Принтери та сканери).',
'QZ_Step_Detect' => '3. Натисніть кнопку ⟳ поруч із «Назва принтера» вище, щоб виявити принтери на цьому комп’ютері, потім оберіть свій принтер етикеток. Залиште поле порожнім, щоб використовувати принтер за замовчуванням.',
'QZ_Step_Cert' => '4. Щоб друкувати без запиту дозволу, завантажте сертифікат нижче та скопіюйте його в папку встановлення QZ Tray, перейменувавши на override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Потім закрийте QZ Tray і запустіть його знову.',
'QZ_Step_Test' => '5. Натисніть «Надрукувати тестову етикетку» нижче. Якщо QZ Tray запитає дозвіл, натисніть Allow — після встановлення сертифіката він більше не запитуватиме.',
'QZ_Step_Save' => '6. Натисніть «Надіслати», щоб зберегти ці налаштування. Етикетки зі сторінки «Друк штрихкодів» тепер друкуватимуться безпосередньо на цьому принтері, без діалогу друку браузера.',
'QZ_Setup_Note' => 'QZ Tray працює на комп’ютері, з якого ви працюєте, тому це спрацює, навіть якщо Stocky розміщено на віддаленому сервері. На кожному комп’ютері, що друкує етикетки, має бути встановлено QZ Tray.',
'PWA_Enabled' => 'Увімкнути встановлюваний застосунок',
'PWA_Enabled_Help' => 'Дозволяє браузерам пропонувати встановити цей застосунок на телефони, планшети й комп’ютери та зберігає кешовані сторінки для роботи офлайн. Вимкнення прибирає запрошення до встановлення всюди та очищає кеш під час наступного відвідування.',
'PWA_Identity' => 'Ідентичність застосунку',
'PWA_Launch' => 'Запуск і вигляд',
'PWA_App_Name' => 'Назва застосунку',
'PWA_App_Name_Help' => 'Показується в запрошенні до встановлення та в списку застосунків. Залиште порожнім, щоб використовувати назву застосунку з налаштувань вигляду.',
'PWA_Short_Name' => 'Коротка назва',
'PWA_Short_Name_Help' => 'Показується під іконкою на головних екранах, де довгі назви обрізаються. Залиште порожнім, щоб використовувати частину назви застосунку до "|".',
'PWA_Description' => 'Опис',
