'PWA_Start_Url' => 'Сторінка запуску',
'PWA_Start_Url_Help' => 'Сторінка, з якої відкривається встановлений застосунок, у вигляді шляху, що починається з "/". Використовуйте /next/pos, щоб запускати одразу POS.',
'PWA_Display_Mode' => 'Режим відображення',
'PWA_Display_Mode_Help' => 'standalone приховує панель браузера; fullscreen також приховує рядок стану; browser відкриває звичайну вкладку.',
'PWA_Orientation' => 'Орієнтація',
