'PWA_Background_Color_Help' => 'Фон заставки, що показується під час запуску застосунку.',
'PWA_Preview' => 'Попередній перегляд',
'PWA_View_Manifest' => 'Переглянути файл маніфесту',
'PWA_Reinstall_Notice' => 'Пристрої, на яких застосунок уже встановлено, зберігають стару назву та іконку, доки його не буде видалено й встановлено знову.',
'Label_Render_Mode' => 'Рендеринг етикетки',
'Label_Render_Mode_Hint' => 'Як малюється етикетка. Шрифти принтера — найшвидше та дає найчіткіший штрихкод, але друкує лише базові латинські символи власним шрифтом принтера. Зображення попереднього перегляду точно відтворює дизайн етикетки — вибраний шрифт, будь-яка мова — як це робить спеціалізоване ПЗ для етикеток.',
'Render_Native' => 'Шрифти принтера (найшвидше)',
'Render_Raster' => 'Зображення попереднього перегляду (точний дизайн)',
'Label_Width_Mm' => 'Ширина етикетки (мм)',
'Label_Height_Mm' => 'Висота етикетки (мм)',
'Label_Size_Hint' => 'Фізичний розмір однієї наклейки на рулоні. Він має точно відповідати завантаженим етикеткам — неправильний розмір змушує принтер шукати проміжок не там, тож кожна етикетка друкується все далі від потрібного положення.',
'Calibrate_Labels' => 'Калібрувати етикетки',
'Calibrate_Labels_Hint' => 'Принтер протягує кілька етикеток, щоб виміряти наклейку та проміжок. Запускайте один раз після встановлення нового рулону або коли положення друку зміщується.',
'Calibration_Sent' => 'Калібрування розпочато — принтер протягне кілька порожніх етикеток для вимірювання. Коли він зупиниться, виконайте тестовий друк.',
'Label_Printer_Dpi' => 'Роздільна здатність друкувальної головки',
'Label_Printer_Dpi_Hint' => 'Більшість принтерів етикеток мають 203 dpi. Не впевнені? Скористайтеся кнопкою «Визначити роздільну здатність» нижче — вона надрукує відповідь.',
'Find_Resolution' => 'Визначити роздільну здатність',
'Find_Resolution_Hint' => 'Друкує дві етикетки з позначками 203 і 300. На правильній видно повний прямокутник на наклейці з невеликим рівним полем з усіх чотирьох боків; на неправильній бракує рамок або вона заходить на наступну наклейку.',
'Dpi_Test_Sent' => 'Друкуються дві етикетки з позначками 203 і 300. На правильній видно повний прямокутник з невеликим рівним полем з усіх чотирьох боків — встановіть «Роздільна здатність друкувальної головки» на це число та збережіть.',
'Label_Offset_X' => 'Горизонтальне зміщення (мм)',
'Label_Offset_X_Hint' => 'Зміщує друк убік на наклейці. Використовуйте, коли текст обрізається з одного бокового краю — напр. 2.5, коли біла наклейка розташована по центру ширшої підкладки. Регулюйте кроком 0.5.',
'Label_Offset_Y' => 'Вертикальне зміщення (мм)',
'Label_Offset_Y_Hint' => 'Зміщує друк уздовж етикетки. Збільште, коли верх дизайну обрізано або відсутній; зменште, коли друк починається занадто низько.',
'Feed_To_Tear' => 'Подача до краю відриву',
'Feed_To_Tear_Hint' => 'Просуває етикетку до планки відриву після кожного завдання. Залиште вимкненим, якщо етикетки друкуються зі зміщенням донизу або розриваються між наклейками — багато принтерів не повертаються назад перед наступною етикеткою.',
