'Enable_Wholesale_Pricing' => 'Оптові ціни за кількістю',
'Enable_Wholesale_Pricing_Hint' => 'Дозвольте товарам мати цінові пороги за кількістю (10-19 шт., 20-49 шт., 100+ ...), які автоматично замінюють роздрібну ціну в POS та онлайн-магазині, щойно замовлена кількість досягає порогу. Вимкніть — і все знову продається за звичайною роздрібною ціною: налаштовані пороги зберігаються, але не застосовуються.',
