'Orders_Guide' => 'Посібник із замовлень',
'Ord_Guide_Intro' => 'Як замовлення з вашого онлайн-магазину потрапляє у ваші запаси та облік і де фактично фіксуються гроші.',
'Ord_Guide_Lifecycle_Title' => 'Статус замовлення',
'Ord_Guide_Lifecycle_Pending' => 'Нове замовлення, що очікує вашого розгляду. Підтвердити або скасувати можна лише замовлення, що очікує.',
'Ord_Guide_Lifecycle_Confirmed' => 'Ви прийняли замовлення. Stocky створює продаж на вибраному складі та списує залишки — саме з цього продажу беруть дані звіти про залишки, платежі та прибуток.',
'Ord_Guide_Lifecycle_Shipped' => 'Ви відправили замовлення. Лише виконання: залишки вже списано під час підтвердження.',
'Ord_Guide_Lifecycle_Delivered' => 'Клієнт отримав замовлення. Саме з цього починається період повернення.',
'Ord_Guide_Lifecycle_Cancelled' => 'Замовлення скасовано до підтвердження, тож продаж не створено і залишки не списано.',
'Ord_Guide_PaymentStatus_Tip' => 'Встановлюється під час оформлення й не редагується тут. Натисніть, щоб дізнатися, як зафіксувати платіж.',
'Ord_Guide_Payment_Title' => 'Статус оплати',
'Ord_Guide_Payment_Intro' => 'Цей стовпець фіксує, як клієнт вирішив сплатити під час оформлення. Його встановлює вітрина і його не можна редагувати на цій сторінці — самі гроші обліковуються на продажі, який створюється під час підтвердження замовлення.',
'Ord_Guide_Payment_Paid' => 'Клієнт уже сплатив онлайн через платіжний шлюз. Підтвердження замовлення створює продаж як «Оплачено» і фіксує платіж за вас — більше нічого робити не потрібно.',
'Ord_Guide_Payment_Pending' => 'Оплата при доставці, банківський переказ або інший спосіб відкладеної оплати. Підтвердження замовлення створює продаж як «Не оплачено», тож ви самі фіксуєте гроші після їх отримання — див. кроки нижче.',
'Ord_Guide_Payment_Failed' => 'Шлюз відхилив платіж або клієнт його не завершив. Замовлення скасовується автоматично.',
'Ord_Guide_MarkPaid_Title' => 'Зміна платежу з «очікує» на «оплачено»',
'Ord_Guide_MarkPaid_Step1' => 'Спочатку підтвердьте замовлення тут — саме підтвердження створює продаж.',
'Ord_Guide_MarkPaid_Step2' => 'Відкрийте Продажі > Усі продажі та знайдіть цей продаж (той самий клієнт, а на сторінці деталей видно онлайн-замовлення, з якого він створений).',
'Ord_Guide_MarkPaid_Step3' => 'Відкрийте меню дій рядка та оберіть «Створити платіж».',
'Ord_Guide_MarkPaid_Step4' => 'Введіть суму, спосіб оплати та дату, потім збережіть. Продаж сам перейде в статус «Частково» або «Оплачено» залежно від суми.',
'Ord_Guide_MarkPaid_Note' => 'Статус оплати, показаний тут, і далі відображає вибір під час оформлення та не змінюється. Продаж є обліковим записом, і саме він живить ваші звіти про платежі та прибуток. Скористайтеся «Показати платежі» на продажі, щоб переглянути або змінити введене.',
'Ord_Guide_Notes_Title' => 'Корисно знати',
'Ord_Guide_Note_Warehouse' => 'Склад, вибраний під час підтвердження, визначає, звідки списуються залишки. Склади, що не можуть покрити все замовлення, позначені в цьому списку як «Немає в наявності».',
'Ord_Guide_Note_Preorder' => 'Товари на передзамовлення пропускають перевірку залишків, тож замовлення з ними можна підтвердити, навіть коли потрібної кількості ще немає.',
'Ord_Guide_Note_Flagged' => 'Тег «Позначено» означає, що замовлення не пройшло перевірку на шахрайство під час оформлення. Наведіть на тег, щоб побачити причину, і перевірте замовлення перед підтвердженням.',
'Ord_Guide_Note_Cancel' => 'Скасувати можна лише замовлення, що ще очікує. Після підтвердження скасовуйте його через продаж або повернення від клієнта.',
