'VG_Opt_Step7' => 'Коди генеруються автоматично. Введіть власний або натисніть іконку оновлення, щоб згенерувати інший.',
'VG_Opt_Step8' => 'Необов’язково: позначте «Кольорові зразки» для опції та виберіть колір для кожного значення; магазин показуватиме його кольоровою крапкою.',
'VG_Rows_Title' => 'Рядки варіантів',
