'Upd_Guide_Before_Title' => '1. Перед оновленням',
'Upd_Guide_Before_Download' => 'Завантажте {package} застосунку з облікового запису CodeCanyon ({path}). Не розпаковуйте його — програмі оновлення потрібен ZIP саме в тому вигляді, в якому його завантажено.',
'Upd_Latest_Full_Zip' => 'останній повний ZIP-пакет',
'Upd_Guide_Before_Admin' => 'Переконайтеся, що ви увійшли як адміністратор із дозволом {perm}. Ніхто інший не може бачити чи запускати програму оновлення.',
'Upd_Guide_Before_Quiet' => 'Виберіть спокійний момент: під час оновлення застосунок ненадовго переходить у режим обслуговування, а інші користувачі не мають доступу.',
'Upd_Guide_Before_No_Manual' => 'Вам {not} потрібно вручну створювати резервні копії, розпаковувати файли, виконувати команди, редагувати файли конфігурації чи працювати з базою даних — програма оновлення робить усе це автоматично. (Додаткова ручна резервна копія, звісно, ніколи не завадить.)',
'Upd_Not' => 'не',
'Upd_Guide_Code_Overwritten' => 'Якщо ви вручну змінювали код застосунку, оновлення перезапише ваші зміни. Ваші дані, завантаження, налаштування та .env завжди зберігаються.',
'Upd_Guide_Running_Title' => '2. Запуск оновлення',
'Upd_Guide_Run_Open' => 'Відкрийте {path} (цю сторінку) та залишайтеся на вкладці {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: натисніть або перетягніть завантажений пакет у поле завантаження. Великі файли завантажуються невеликими частинами, тому це працює навіть на спільному хостингу з низькими лімітами завантаження. Контрольна сума захищає від пошкоджених або неповних завантажень.',
'Upd_Upload_The_Zip' => 'Завантажте ZIP',
'Upd_Guide_Run_Validation' => '{auto} після завантаження (її можна повторити кнопкою {button}). Система перевіряє: цілісність ZIP, структуру та повноту пакета, сумісність версій (пониження версії відхиляється), потрібну версію PHP і розширення, права доступу до файлів, вільне місце на диску, з\'єднання з базою даних, конфігурацію, а також відсутність інших запущених оновлень.',
'Upd_Validation_Runs_Automatically' => 'Перевірка запускається автоматично',
'Upd_Guide_Run_Review' => 'Перегляньте панель {panel}. Кнопка {button} з\'являється лише тоді, коли пройдено всі критичні перевірки. Якщо перевірка не пройдена, повідомлення точно вказує, що потрібно виправити.',
'Upd_Guide_Run_Click' => 'Натисніть {button} і підтвердьте. Потім просто {keep} і стежте за індикатором прогресу. Система виконує по черзі:',
'Upd_Keep_Page_Open' => 'залиште цю сторінку відкритою',
'Upd_Guide_Phase_Backup' => '{label} — створюються та {verified} повний дамп бази даних, ZIP усіх файлів застосунку, які може змінити оновлення, і копія {env}. Ваші завантаження ({images}) і {storage} ніколи не зачіпаються оновленням, тому не архівуються. Якщо резервну копію неможливо створити, оновлення зупиняється тут і нічого не змінюється.',
'Upd_Verified' => 'перевіряються',
'Upd_Guide_Phase_Prepare' => '{label} — нова версія розпаковується в проміжну область і перевіряється ще раз. Робочий застосунок досі не зачіпається.',
'Upd_Guide_Phase_Maintenance' => '{label} — вмикається режим обслуговування; відвідувачі бачать дружній екран «Ми скоро повернемося».',
'Upd_Guide_Phase_Files' => '{label} — нові файли підміняються майже миттєво; старі файли зберігаються окремо для відкату. Захищені шляхи ({env}, {storage}, {images}) ніколи не замінюються.',
'Upd_Guide_Phase_Database' => '{label} — виконуються міграції, після чого оновлюються дозволи, переклади та шаблони.',
'Upd_Guide_Phase_Cache' => '{label} — усі кеші очищаються та перебудовуються.',
'Upd_Guide_Phase_Verify' => '{label} — перевірки стану підтверджують, що нова версія запускається, база даних працює, усі міграції виконано, а конфігурація коректна.',
'Upd_Guide_Phase_Done' => '{label} — режим обслуговування вимикається, а тимчасові файли видаляються.',
'Upd_Guide_Run_Success' => 'Коли побачите {success}, натисніть {reload} і повністю оновіть сторінку браузера ({keys}), щоб завантажилися нові ресурси панелі адміністратора.',
'Upd_Update_Successful_Short' => 'Оновлення успішне',
'Upd_Guide_No_Internet' => 'Під час оновлення підключення до інтернету не потрібне — усе береться із завантаженого ZIP. Втрата з\'єднання чи закриття браузера НЕ порушує оновлення: сервер точно пам\'ятає, де зупинився.',
'Upd_Guide_Wrong_Title' => '3. Якщо щось пішло не так',
'Upd_Guide_Wrong_Rollback' => '{label} — якщо щось не вдається після початку зміни файлів (помилка розпакування, збій міграції, невдала перевірка стану, переповнений диск, …), система автоматично відновлює попередні файли та базу даних із перевіреної резервної копії, вимикає режим обслуговування і повідомляє {message}. Ви повертаєтеся точно до початкового стану.',
'Upd_Automatic_Rollback' => 'Автоматичний відкат',
'Upd_Failed_Previous_Restored' => 'Оновлення не вдалося — попередню версію відновлено',
'Upd_Guide_Wrong_Interrupted' => '{label} (перезапуск сервера, тайм-аут, закритий браузер, вимкнення живлення) — коли ви знову відкриєте цю сторінку, червоний банер запропонує два безпечні варіанти: {resume} (продовжує з того самого кроку, де зупинилося) або {rollback} (відновлює попередню версію з резервної копії).',
'Upd_Interrupted_Update' => 'Перерване оновлення',
'Upd_Guide_Wrong_Unreachable' => '{label} — скористайтеся окремою {console} за адресою {path}. Вона працює навіть тоді, коли сайт у режимі обслуговування або ресурси панелі адміністратора пошкоджені, і пропонує ті самі дії «Продовжити / Відкотити». Також унизу екрана обслуговування є непомітне посилання «Доступ адміністратора».',
'Upd_Admin_Unreachable' => 'Панель адміністратора недоступна',
'Upd_Recovery_Console' => 'консоллю відновлення',
'Upd_Guide_Wrong_Locked_Out' => '{label} — під час оновлення ця сторінка показує {link}. Збережіть його, якщо потрібно буде повернутися (наприклад, після завершення сеансу); воно дозволяє пройти екран обслуговування, щоб знову увійти.',
'Upd_Locked_Out_Maintenance' => 'Заблоковано режимом обслуговування',
'Upd_Bypass_Link' => 'посилання для обходу',
'Upd_Guide_Wrong_Concurrent' => '{label} — вони побачать {message} Одночасно може виконуватися лише одне оновлення.',
'Upd_Another_Admin_Updating' => 'Інший адміністратор намагається оновити одночасно',
'Upd_Guide_Backups_Title' => '4. Резервні копії та відновлення',
'Upd_Guide_Backups_Created' => 'Кожне оновлення створює резервну копію {before} будь-яких змін: усі файли застосунку, які може замінити оновлення, копію {env} і повний дамп бази даних. Завантаження та {storage} ніколи не змінюються оновленням, тому до неї не входять — зберігайте власні резервні копії цих даних. Резервні копії зберігаються в {path} і ніколи не доступні з вебу.',
'Upd_Before' => 'до',
'Upd_Guide_Backups_Panel' => 'Панель {panel} на вкладці {tab} показує їх із датою, версією та розміром. Звідти можна {restore} будь-яку повну резервну копію (файли + база даних — спершу створюється страхова копія поточної бази даних) або {delete} старі.',
'Upd_Restore_Verb' => 'відновити',
'Upd_Delete_Verb' => 'видалити',
'Upd_Guide_Backups_Retention' => 'Параметром {keep} задайте кількість збережених резервних копій; старіші видаляються автоматично після кожного успішного оновлення. Єдину повну резервну копію, що залишилася, видалити неможливо — у вас завжди є шлях назад.',
'Upd_Guide_Manual_Title' => '5. Ручне оновлення (резервний спосіб)',
'Upd_Guide_Manual_Text' => 'Якщо ви бажаєте оновлювати вручну або програму завантаження неможливо використовувати на вашому сервері, дотримуйтеся покрокових інструкцій на вкладці {tab} цієї сторінки.',
'Upd_Guide_Clear_Cache_First' => 'Якщо після будь-якого оновлення сторінки виглядають пошкодженими або порожніми, спершу очистьте кеш браузера — майже завжди причина саме в цьому.',
'Upd_Restore_Backup_Confirm' => 'Відновити цю резервну копію? Поточні файли та поточну базу даних буде замінено резервною копією. Спершу створюється страхова копія поточної бази даних. (v{version} — {date})',
'Woo_Guide_Lead' => 'Як магазин WooCommerce підтримує синхронізацію з ERP. Наведені нижче рядки cron складено для цього сервера, тож їх можна скопіювати безпосередньо на нього.',
'Woo_Guide_Ways_Note' => 'На відміну від Shopify, WooCommerce нічого не надсилає в ERP самостійно — тут немає приймача вебхуків, тож усе, що надходить {in}, надходить за розкладом. Миттєвим може бути лише передавання запасів {out}.',
'Woo_In' => 'всередину',
'Woo_Out' => 'назовні',
'Woo_Guide_Both_Ways_Title' => 'Для обох напрямків спершу потрібно це',
'Woo_Api_Keys' => 'Ключі API',
'Woo_Guide_Api_Keys_Text' => '{path}, дозвіл {perm}. Скопіюйте ключ і секрет споживача на вкладку {settings} разом з URL магазину — адресою вашого сайту без кінцевої скісної риски, напр. {example}.',
'Woo_Credentials_Saved' => 'облікові дані збережено',
'Woo_Not_Configured_Yet' => 'ще не налаштовано',
'Woo_Guide_Wp_App_Password_Title' => 'Пароль застосунку WordPress (необов\'язково)',
'Woo_Guide_Wp_App_Password_Text' => 'Використовується лише для зображень товарів. API WooCommerce передає товари, запаси, категорії, бренди, клієнтів і замовлення; API WordPress шукає в медіатеці та завантажує зображення, якого там ще немає.',
'Woo_Guide_Wp_App_Password_Note' => 'Використовуйте користувача WordPress, який може керувати медіафайлами, і створіть пароль у {path}. Залиште обидва поля порожніми — усе одно все синхронізуватиметься, пропускатиметься лише прикріплення зображень.',
'Woo_Guide_Pick_Way_Title' => 'Потім виберіть спосіб синхронізації',
'Woo_Right_Away' => 'Одразу',
'Woo_Stock_Live' => 'запаси наживо',
'Woo_Stock_Not_Live' => 'запаси не наживо',
'Woo_Guide_Realtime_Lead' => 'Лише в одному напрямку: запаси й товари, що виходять з ERP. Замовлення та зміни товарів, зроблені у WooCommerce, і далі надходять за розкладом — див. іншу вкладку.',
'Woo_Push_Stock_On_Change' => 'Передавати запаси одразу після зміни',
'Woo_Setting_People_Miss' => 'Це налаштування часто пропускають',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Продаж POS {not} потрапляє у WooCommerce сам собою. Якщо його вимкнено, магазин дізнається про це лише під час наступної синхронізації запасів — за замовчуванням через годину, — і за цей час може продати одиницю, яку ви вже продали на касі.',
'Woo_Does_Not' => 'не',
'Woo_Guide_Tick_Instant' => 'Позначте {option} на вкладці {settings}. Це все налаштування — без воркера, без cron. Кожен продаж, повернення, коригування, переміщення та отримана закупівля надсилають оновлення лише для відповідних товарів одразу після збереження продажу, а продаж із двадцяти рядків — це одне надсилання, а не двадцять. Каса ніколи на нього не чекає.',
'Woo_Currently' => 'Зараз:',
'Woo_Instant_On_Text' => 'увімк. — запаси передаються під час зміни',
'Woo_Instant_Off_Text' => 'вимк. — запаси лише за розкладом',
'Woo_Guide_Instant_Note' => 'Передаються лише товари, вже пов\'язані з WooCommerce, — у товару, який ніколи не синхронізувався, немає нічого в магазині для виправлення. Варіативні товари передаються через батьківський товар, а комплект передається повторно, коли змінюється будь-який із його компонентів. Масові операції (видалення товару, скидання складу) записують запаси без генерування події, і це одна з причин зберігати також щогодинну синхронізацію запасів.',
'Woo_Push_Products_On_Save' => 'Передавати товари одразу після збереження',
'Woo_Guide_Tick_Auto_Products' => 'Позначте {option} на вкладці {settings}, і товар, створений, змінений чи дубльований у Stocky, надсилатиметься у WooCommerce одразу після збереження — відомості, ціна, варіанти та зображення, а потім запаси. Новий товар створюється в магазині одразу, без очікування нічної синхронізації товарів.',
'Woo_On' => 'увімк.',
'Woo_Off' => 'вимк.',
'Woo_Guide_Bulk_Imports_Note' => 'Масові імпорти не передаються поштучно — після імпорту запустіть синхронізацію товарів. Спершу синхронізуйте категорії та бренди, щоб переданий товар потрапив у правильну категорію.',
'Woo_Nothing_Else_To_Install' => 'Більше нічого встановлювати не потрібно',
'Woo_Guide_Same_Process' => 'Без воркера черги, без запису cron. Передавання виконується в тому самому процесі, що обслуговував продаж, {after} того, як відповідь повернулася, тож каса ніколи не чекає на WooCommerce. Передавання ніколи не перетинаються: зміни, зроблені під час виконання одного, чекають на нього й надсилаються одразу після.',
'Woo_After' => 'після',
'Woo_Guide_Shop_Stops_Answering' => 'Якщо магазин перестає відповідати, спроба припиняється через вісім секунд, а передавання призупиняються на п\'ять хвилин, щоб кожен продаж знову не чекав на нього; зміни, що надійшли за цей час, надсилаються з першим передаванням після паузи, а щогодинна синхронізація запасів у будь-якому разі все наздоганяє. Кожна пауза записується на вкладці «Журнали».',
'Woo_Guide_Artisan_Exception' => 'Один виняток: зміна запасів, зроблена командою artisan, не має відповіді, після якої можна виконати передавання, тож вона ставиться в чергу {queue}. Щоб такі зміни теж надсилалися оперативно, обробляйте цю чергу:',
'Woo_Cron_Line_Copied' => 'Рядок cron скопійовано',
'Woo_Command_Copied' => 'Команду скопійовано',
'Woo_Guide_Not_Woo_Queue' => 'Навмисно не черга {queue}: вона обробляє багатогодинні пакети каталогу, і миттєве передавання за одним із них уже не було б миттєвим.',
'Woo_On_A_Schedule' => 'За розкладом',
'Woo_Guide_Scheduled_Lead' => 'Усе періодично перевіряється в обох напрямках. Так замовлення потрапляють в ERP, так публікується каталог і так виправляється все, що пропустив швидкий шлях. Кожне завдання має власний запис cron, тож ви запускаєте лише потрібне.',
'Woo_Guide_Sync_Drains_Queue' => '{command} сама обробляє свою чергу під час роботи, тож для цих рядків не потрібен окремий воркер. У Windows використовуйте Планувальник завдань із програмою {program} і тими самими аргументами, запускаючи в {path}.',
'Woo_Or_No_Cron' => 'Або взагалі без cron',
'Woo_Guide_No_Cron_Text' => 'Кожна вкладка тут синхронізується на вимогу, а ручна синхронізація сама обробляє свої пакети, поки сторінка відкрита, — тож невеликий магазин може працювати взагалі без записів cron. Ви втрачаєте все, що відбувається, поки ніхто не дивиться: замовлення надходять лише тоді, коли хтось натискає кнопку.',
'Woo_Commands_Worth_Knowing' => 'Корисні команди',
'Woo_Worth_Knowing' => 'Варто знати',
'Woo_Guide_Changing_Url_Clears' => 'Зміна URL магазину або ключів API очищує всі зіставлення — товари, категорії, бренди та клієнти синхронізуються заново з новим магазином.',
'Woo_Guide_Keep_Skus' => 'Підтримуйте узгоджені SKU у Stocky та WooCommerce: саме це запобігає дублікатам і робить повторне пов\'язування безпечним.',
'Woo_Guide_Stock_Total' => 'Запаси, що публікуються у Woo, — це {total}, а не показник одного складу.',
'Woo_Total_Across_Warehouses' => 'загальна кількість на всіх складах',
'Woo_Guide_Full_Reference' => 'Повний довідник — усі області, поведінка черги та список усунення несправностей — міститься у {file}.',
'Woo_Way_Covers' => 'Охоплює',
'Woo_Way_Covers_Realtime' => 'Лише запаси, що виходять з ERP, — продаж POS, повернення, коригування, отримана закупівля',
'Woo_Way_Covers_Scheduled' => 'Усе в обох напрямках: замовлення та зміни товарів усередину, каталог і запаси назовні',
'Woo_Way_Speed' => 'Швидкість',
'Woo_Way_Seconds' => 'Секунди',
'Woo_Way_Speed_Scheduled' => 'Залежно від запису cron (запаси щогодини, замовлення кожні 15 хв)',
'Woo_Way_Needs' => 'Потрібно',
'Woo_Way_Needs_Realtime' => 'Нічого — лише налаштування',
'Woo_Way_Needs_Scheduled' => 'Запис cron для кожного завдання — або нічого, якщо синхронізуєте вручну',
'Woo_Way_Switched_On_At' => 'Вмикається в',
'Woo_Way_Cron_Entries_Below' => 'Записи cron нижче',
'Woo_Cron_Orders' => 'Замовлення кожні 15 хвилин — лише змінені після останнього запуску.',
'Woo_Cron_Products_Pull' => 'Зміни товарів із магазину, щоночі о 03:00.',
'Woo_Cron_Customers' => 'Клієнти, щоночі о 03:30.',
'Woo_Cron_Stock' => 'Запаси щогодини — страховка для миттєвого передавання і єдина синхронізація запасів без нього.',
'Woo_Cron_Products_Push' => 'Ще не пов\'язані товари, щоночі о 02:00. Наявні товари не перезаписуються.',
'Woo_Cmd_Stock' => 'Передати запаси для всіх пов\'язаних товарів зараз.',
'Woo_Cmd_Products_Unsynced' => 'Опублікувати товари, які ще не мають id WooCommerce.',
'Woo_Cmd_Orders' => 'Імпортувати замовлення, змінені після останнього запуску.',
'Woo_Cmd_Orders_Full' => 'Повторно сканувати всі замовлення, а не лише останні зміни.',
'Woo_Cmd_Pull' => 'Усе вхідне одразу: товари, замовлення, клієнти.',
'Woo_Guide_Page_Title' => 'Посібник WooCommerce',
'Woo_Guide_Page_Subtitle' => 'Підключення магазину, що працює самостійно, і записи cron для цього сервера',
'Woo_Settings_Button' => 'Налаштування WooCommerce',
'Woo_No_Shop_Connected' => 'Жоден магазин ще не підключено',
'Woo_No_Shop_Connected_Desc' => 'Усе наведене нижче залишається чинним — введіть URL магазину та ключі API на сторінці налаштувань WooCommerce, а потім поверніться.',
'Woo_Wp_Username' => 'Ім\'я користувача WordPress',
'Woo_Wp_App_Password' => 'Пароль застосунку WordPress',
'Woo_Settings_Instant_Hint' => 'Продаж, повернення чи коригування надсилає оновлення запасів лише для відповідних товарів у момент збереження, тож магазин актуальний за лічені секунди, а не під час наступної щогодинної синхронізації запасів. Більше нічого встановлювати не потрібно — передавання виконується після обробки продажу, тож каса ніколи не чекає на WooCommerce. Докладніше на вкладці {guide}.',
'Woo_Settings_Instant_Off_Alert' => 'Якщо залишити вимкненим, продаж POS потрапить у WooCommerce лише під час наступної синхронізації запасів — до години пізніше.',
'Woo_Settings_Auto_Products_Hint' => 'Товар, створений, змінений чи дубльований у Stocky, надсилається у WooCommerce одразу після збереження — відомості, ціна, варіанти, зображення, а потім запаси — без очікування синхронізації товарів. Масові імпорти не передаються; після імпорту запустіть синхронізацію товарів.',
'Woo_Sync_Tuning' => 'Налаштування синхронізації',
'Woo_Sync_Tuning_Intro' => 'Значення за замовчуванням підходять більшості магазинів. Змінюйте їх, лише якщо синхронізація повільна або перевищує час очікування на вашому хостингу. Кожне значення обмежене безпечним діапазоном, а очищення поля відновлює значення за замовчуванням.',
'Woo_Setting_This_Up' => 'Налаштування',
'Woo_Setting_This_Up_Text' => 'Отримання ключів API, для чого потрібен пароль застосунку WordPress, записи cron для синхронізації за розкладом і як зробити так, щоб запаси потрапляли в магазин одразу після зміни, — усе це, з готовими до копіювання рядками cron для цього сервера, міститься на вкладці «Посібник». Одна копія, тож вона не може розійтися з тим, що насправді робить модуль.',
'Woo_Open_The_Guide' => 'Відкрити посібник',
'Woo_Sync_Stock' => 'Синхронізувати запаси',
'Woo_Orders_Stat' => 'Замовлення WooCommerce',
'Woo_Imported' => 'Імпортовано',
'Woo_Imported_Today' => 'Імпортовано сьогодні',
'Woo_Unknown_Error' => 'Невідома помилка',
