'Presta_Push_Products_Desc' => 'Створює відсутні прості товари в PrestaShop (з їхніми поточними запасами). Уже пов\'язані товари та товари з варіантами пропускаються — продовжуйте редагувати відомості про товари в PrestaShop або отримайте їх, щоб оновити локальну копію.',
'Presta_Pull_Products_Desc' => 'Імпортує товари PrestaShop, зіставляючи наявні за артикулом (SKU) та створюючи решту. Комбінації імпортуються як їхній батьківський товар.',
