'Presta_Guide_4' => 'Спершу отримайте товари, якщо в магазині вже є каталог (зіставлення за артикулом/SKU); передайте, щоб створити відсутні прості товари.',
'Presta_Guide_5' => 'Передавайте запаси щоразу, коли змінюються кількості, і регулярно отримуйте замовлення — PrestaShop не має вебхуків, тож замовлення надходять лише під час отримання.',
