'Jumia_Hero_Title' => 'Синхронізація маркетплейсу Jumia',
'Jumia_Hero_Desc' => 'Передавайте ціни та запаси у свої оголошення Jumia Seller Center та імпортуйте замовлення маркетплейсу як продажі.',
'Jumia_Api_Url_Label' => 'API URL (кінцева точка Seller Center вашої країни)',
'Jumia_Account_Email' => 'Email облікового запису (User ID)',
'Jumia_Api_Key' => 'Ключ API',
'Jumia_Prices_Stock' => 'Ціни та запаси',
'Jumia_Push_Prices_Stock_Title' => 'Передати ціни та запаси в Jumia',
'Jumia_Push_Prices_Stock_Desc' => 'Надсилає поточну ціну та кількість для кожного товару (і варіанта), SKU якого відповідає {sku} оголошення Jumia. Оновлення надсилаються як фіди Seller Center і застосовуються асинхронно — ID фіду записується на вкладці «Журнали», а відхилення окремих позицій відображаються на екрані статусу фідів Seller Center.',
'Jumia_Push_Prices_Stock' => 'Передати ціни та запаси',
'Jumia_Pull_Orders_Desc' => 'Імпортує замовлення маркетплейсу як продажі (номери на кшталт {ref}), зіставляючи з вашими товарами за Seller SKU. Уже імпортовані та скасовані замовлення пропускаються, тож регулярне отримання безпечне. Платежі позначаються як оплачені лише для доставлених замовлень (у Jumia переважає оплата при отриманні).',
'Jumia_Guide_1' => 'У Jumia {sellerCenter} відкрийте {menu} та згенеруйте ключ API.',
'Jumia_Guide_2' => 'Введіть API URL вашої країни (напр. {ng} для Нігерії, {ke} для Кенії, {eg} для Єгипту), email облікового запису Seller Center і ключ — потім запустіть {test}.',
'Jumia_Guide_3' => 'Переконайтеся, що {sku} кожного оголошення Jumia дорівнює коду товару Stocky — саме цей ідентифікатор використовується і для передавання запасів, і для зіставлення замовлень.',
'Jumia_Guide_4' => 'Передавайте ціни та запаси після змін у запасах; регулярно отримуйте замовлення (у цьому API Jumia немає вебхуків).',
'Jumia_Guide_5' => 'Створення нових оголошень залишається в Seller Center — Jumia вимагає атрибутів, специфічних для категорії, та перевірки зображень, з чим добре справляється лише їхній портал.',
'Mailchimp_Hero_Title' => 'Синхронізація аудиторії Mailchimp',
'Mailchimp_Hero_Desc' => 'Наповнюйте аудиторію Mailchimp своїми клієнтами, щоб проводити email-кампанії на реальній клієнтській базі.',
'Mailchimp_Account_Audience' => 'Обліковий запис і аудиторія',
'Mailchimp_Api_Key_Ph' => 'напр. {example} ({menu})',
'Mailchimp_Audience_Option' => '{name} (учасників: {n})',
'Mailchimp_Load_Audiences_Ph' => 'Завантажте аудиторії, щоб вибрати одну',
'Mailchimp_Load_Audiences' => 'Завантажити аудиторії',
'Mailchimp_Double_Optin_Label' => 'Подвійне підтвердження — нові учасники отримують лист підтвердження перед приєднанням',
'Mailchimp_Double_Optin_Hint' => '(рекомендовано для GDPR)',
'Mailchimp_Auto_Sync_Customers' => 'Автоматично синхронізувати нових клієнтів у міру їх створення',
'Mailchimp_With_Email' => 'З email',
'Mailchimp_Push_Desc' => 'Додає або оновлює у вибраній аудиторії кожного клієнта, який має адресу email (разом з ім\'ям і телефоном). Наявні учасники зберігають свій статус підписки — нікого з тих, хто відписався, не буде підписано знову. Клієнти без email не враховуються.',
'Mailchimp_Double_Optin_Off_Title' => 'Подвійне підтвердження вимкнено',
'Mailchimp_Double_Optin_Off_Desc' => 'Нових учасників буде додано як підписаних без листа підтвердження. Робіть це лише для клієнтів, які вже погодилися отримувати маркетингові матеріали.',
'Mailchimp_Guide_1' => 'У Mailchimp відкрийте {menu} та створіть ключ (він закінчується на {suffix} — цей суфікс і є вашим дата-центром).',
'Mailchimp_Guide_2' => 'Вставте ключ сюди, збережіть, потім натисніть {load} і виберіть аудиторію для наповнення.',
'Mailchimp_Guide_3' => 'Залиште {doubleOptIn} увімкненим, якщо ваші клієнти ще не погодилися на маркетингові листи.',
'Mailchimp_Double_Optin_Term' => 'подвійне підтвердження',
'Mailchimp_Guide_4' => 'Запустіть {push} для початкового наповнення; увімкніть {autoSync}, щоб нові клієнти приєднувалися автоматично.',
'Mailchimp_Auto_Sync_Term' => 'автосинхронізацію',
'Mailchimp_Consent_Title' => 'Згода має значення',
'Mailchimp_Consent_Desc' => 'Надсилання листів людям, які ніколи не погоджувалися на маркетинг, може порушувати GDPR/CAN-SPAM і призвести до блокування вашого облікового запису Mailchimp. Подвійне підтвердження перекладає підтвердження на Mailchimp — це безпечний варіант за замовчуванням.',
'Mailchimp_No_Audiences' => 'У цьому обліковому записі не знайдено аудиторій.',
