'Shopify_Auto_Schedule_Hint' => 'Потрібен запис cron на сервері, що запускає {cmd} (кожні 5 хвилин — найдрібніший інтервал, який можуть використовувати наведені нижче налаштування). Синхронізацію завжди можна запустити вручну.',
