'Shopify_Hook_Note_Register' => 'Реєстрація створює підписки в Shopify й автоматично спрямовує їх на цю адресу. Не додавайте її вручну в Shopify → Settings → Notifications → Webhooks: такі вебхуки підписуються іншим секретом, і кожна доставка буде відхилена.',
