'Shopify_Could_Not_Load_Store' => 'Не вдалося завантажити цей магазин',
'Shopify_G_Lead_Store' => 'Що потрібно цьому магазину для підтримання синхронізації. Усе тут стосується саме цього магазину — шляхи та ID справжні, тож команди можна скопіювати безпосередньо на сервер.',
'Shopify_G_Lead_Generic' => 'Як магазин Shopify підтримує синхронізацію з ERP. Виберіть магазин вище, щоб побачити його стан, або читайте як є — рядок cron і URL вебхука однакові для будь-якого магазину, який ви підключите.',
'Shopify_G_Ways_Note' => 'Більшість магазинів використовують обидва способи: перший підтримує актуальність магазину щохвилини, другий підхоплює все, що пропустив перший, — вебхук, який так і не надійшов, зміну, внесену безпосередньо в панелі адміністратора Shopify, ніч, коли сайт не працював.',
'Shopify_G_Both_Need' => 'Для обох напрямків спершу потрібно це',
'Shopify_G_Credentials' => 'Облікові дані Shopify',
'Shopify_G_Cred_Intro' => 'З січня 2026 року Shopify більше не створює власні застосунки в панелі адміністратора, тому існує два типи підключення:',
'Shopify_G_Cred_DevDash' => '{app} (будь-який магазин, що підключається зараз) — {path}. Надайте області Admin API для того, що синхронізує цей магазин, встановіть застосунок у магазині, потім скопіюйте {clientId} і {clientSecret} зі сторінки Settings застосунку в {where}. ERP самостійно обмінює їх на токен доступу та оновлює його до спливання кожні 24 години. Client secret також підписує вебхуки, тож більше нічого не потрібно. Застосунок і магазин мають бути в одній організації Shopify.',
'Shopify_G_Dev_Dashboard_App' => 'Застосунок Dev Dashboard',
'Shopify_G_Cred_Legacy' => '{app} (створений у панелі адміністратора до 2026 року) — продовжує працювати без змін зі своїм {token} ({prefix}) і своїм {secret} як секретом підпису вебхуків. Це не те саме значення, що й токен, і плутанина між ними — звичайна причина відхилення вебхуків.',
'Shopify_G_Legacy_App' => 'Застарілий власний застосунок',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'збережено',
'Shopify_G_Missing_Refused' => 'відсутній — доставки відхилятимуться',
'Shopify_G_Where_Data_Desc' => '{path} Склад ERP, запаси якого продає цей магазин, і локація Shopify, куди записуються ці запаси. Синхронізація запасів та імпорт замовлень без них не запускаються.',
'Shopify_G_Currently' => 'Зараз: склад {warehouse}, локація {location}',
'Shopify_G_Not_Set_Lower' => 'не встановлено',
'Shopify_G_Ready' => 'готово',
'Shopify_G_Incomplete' => 'неповно',
'Shopify_G_Manual_Syncs' => 'Синхронізації, що запускаються вручну',
'Shopify_G_Manual_Desc' => 'Синхронізація, запущена з {centre}, відповідає одразу й виконується у фоновому режимі короткими частинами, кожна з яких продовжує з місця зупинки попередньої. Великий каталог ніколи не обривається на півдорозі через хостинг, що завершує довгі веб-запити (LiteSpeed, nginx, балансувальник навантаження), а закриття сторінки її не зупиняє. Воркер для цього — ще один рядок cron:',
'Shopify_G_Cron_Copied' => 'Рядок cron скопійовано',
'Shopify_G_Manual_Note' => 'Без нього синхронізація однаково завершиться, але лише поки сторінка Центру синхронізації відкрита: якщо жоден воркер не підхопить запуск протягом кількох секунд, сторінка продовжить його сама, по одному короткому запиту. У Windows використовуйте Планувальник завдань щохвилини: програма {program}, аргументи {args}, запуск у {dir}.',
'Shopify_G_Then_Pick' => 'Потім виберіть спосіб синхронізації',
'Shopify_G_Right_Away' => 'Одразу',
'Shopify_G_Stock_Live' => 'запаси наживо',
'Shopify_G_Stock_Not_Live' => 'запаси не наживо',
'Shopify_G_Realtime_Lead' => 'Кожна зміна надсилається в момент виникнення, за лічені секунди. Дві половини, і це окремі перемикачі: {webhooks} передають власні події магазину всередину, а {push} надсилає запаси назовні.',
'Shopify_G_Webhooks_Lower' => 'вебхуки',
'Shopify_G_Instant_Push_Lower' => 'миттєве передавання запасів',
'Shopify_G_Webhooks_In' => 'Вебхуки — магазин → ERP',
'Shopify_G_Webhooks_Desc' => 'Замовлення, зміни статусу замовлень, а також зміни товарів, клієнтів і запасів, внесені в Shopify. Відкрийте магазин і натисніть {button} на його {tab} — можна натискати двічі. Shopify надсилає на:',
'Shopify_G_Webhooks_Tab' => 'вкладці «Вебхуки»',
'Shopify_G_Webhooks_Note' => 'Адреса має бути доступна з інтернету через HTTPS — Shopify не доставляє на {localhost} або домен {test}. Кожна доставка записується один раз, тож повторні спроби Shopify не можуть створити дублікат замовлення, а невдалу доставку можна повторити. Доставки відхиляються, доки не збережено секрет підпису з кроку 1.',
'Shopify_G_Instant_Out' => 'Миттєве передавання запасів — ERP → магазин',
'Shopify_G_Setting_Missed' => 'Це налаштування часто пропускають',
'Shopify_G_Pos_Not_Auto' => 'Продаж POS {not} потрапляє в Shopify сам собою. Якщо його вимкнено, магазин дізнається про це лише під час наступного кроку передавання запасів — і за цей час може продати одиницю, яку ви вже продали на касі.',
'Shopify_G_Not' => 'не',
'Shopify_G_Tick_Push' => 'Позначте {setting} у {where}. Це все налаштування — без воркера, без cron. Кожен продаж, повернення та коригування надсилають оновлення лише для відповідних товарів одразу після збереження продажу, а продаж із двадцяти рядків — це одне надсилання, а не двадцять. Каса ніколи на нього не чекає.',
'Shopify_G_This_Store' => 'Цей магазин:',
'Shopify_G_Push_On' => 'увімк. — запаси передаються під час зміни',
'Shopify_G_Push_Off' => 'вимк. — запаси лише за розкладом',
'Shopify_G_Push_Note' => 'Передаються лише товари, які вже мають зіставлення в Shopify, і лише рухи на складі цього магазину. Масові операції — видалення товару, скидання складу — записують запаси без генерування події, і це одна з причин зберігати також запланований крок запасів.',
'Shopify_G_Nothing_Install' => 'Більше нічого встановлювати не потрібно',
'Shopify_G_No_Worker_Note' => 'Жодна з половин не потребує воркера черги чи запису cron. Вхідний вебхук обробляється в запиті, який робить Shopify; вихідне передавання запасів виконується в тому самому процесі, що обслуговував продаж, {after} того, як відповідь повернулася, — тож каса ніколи не чекає на Shopify, а якщо магазин перестає відповідати, спроба припиняється через десять секунд і залишається для наступного запланованого передавання запасів.',
'Shopify_G_After' => 'після',
'Shopify_G_Artisan_Note' => 'Один виняток: зміна запасів, зроблена командою artisan, не має відповіді, після якої можна виконати передавання, тож вона ставиться в чергу {queue}. Якщо ви хочете, щоб такі зміни теж надсилалися оперативно, обробляйте цю чергу:',
'Shopify_G_On_Schedule' => 'За розкладом',
'Shopify_G_On_Lower' => 'увімк.',
'Shopify_G_Off_Lower' => 'вимк.',
'Shopify_G_Scheduled_Lead' => 'Усе періодично перевіряється в обох напрямках. Повільніше, ніж у реальному часі, але саме так передаються запаси в магазинах без миттєвого передавання, так підхоплюється пропущений вебхук, і це єдиний спосіб перемістити весь каталог.',
'Shopify_G_Cron_Entry' => 'Запис cron',
'Shopify_G_Cron_Entry_Desc' => 'Без нього нічого заплановане не виконується. Один рядок, лише для цього модуля — додайте його поряд із тим, що ви вже запланували:',
'Shopify_G_Cron_Note' => 'Кожні п\'ять хвилин — найдрібніша роздільність, яку може використовувати план, оскільки п\'ять хвилин — найкоротший інтервал кроку. Грубіший запис просто стає нижньою межею — з {example} крок, налаштований на 5 хвилин, виконується кожні 15. У Windows використовуйте Планувальник завдань: програма {program}, аргументи {args}, запуск у {dir}.',
'Shopify_G_Switch_On_Plan' => 'Увімкніть і виберіть план',
'Shopify_G_Plan_Desc' => '{where} Перемикач вирішує, чи може cron взагалі діяти; план визначає, що саме він робить. {step} — це одна сутність в одному напрямку з власним інтервалом — {first}, {second}. Інтервал за замовчуванням використовується для будь-якого кроку, у якого власне поле порожнє.',
'Shopify_G_Step_Lower' => 'Крок',
'Shopify_G_Plan_Note' => 'Залиште план порожнім, і магазин отримуватиме замовлення та передаватиме запаси з інтервалом за замовчуванням, чого й потребує більшість магазинів. Замовлення лише отримуються: саме в Shopify клієнт їх розміщує.',
'Shopify_G_Schedule_On' => 'розклад увімк.',
'Shopify_G_Schedule_Off' => 'розклад вимк. — лише вручну',
'Shopify_G_When_Step_Runs' => 'Коли крок справді виконується',
'Shopify_G_When_Note' => 'Крок готовий до виконання, коли той самий крок востаннє {started} давніше, ніж його інтервал, за даними історії запусків. Тож синхронізація, запущена вручну, відкладає наступну автоматичну, а крок, що постійно завершується помилкою, повторюється згідно зі своїм інтервалом, а не на кожному такті. Огляд магазину показує для кожного кроку останній запуск, наступний час виконання та причину блокування, якщо вона є. Перше передавання каталогу виконайте вручну — спершу з {dryRun} — перш ніж ставити його в розклад.',
'Shopify_G_Started_Lower' => 'запускався',
'Shopify_G_Where_Setting' => 'Де розташовані налаштування',
'Shopify_G_Where_Setting_Note' => 'Усі вони — в наявному магазині: {path}, потім олівець (або {edit} на сторінці самого магазину).',
'Shopify_G_Product_Images' => 'Зображення товарів',
'Shopify_G_Img_1' => 'Зображення надсилаються разом із товаром під час {push} — спочатку головне зображення, потім галерея, потім по одному для кожного варіанта з власним зображенням, до п\'ятдесяти.',
'Shopify_G_Products_Push' => 'передавання товарів',
'Shopify_G_Img_2' => 'Зображення варіанта завантажується разом із товаром, а потім {assigned}, як це моделює Shopify: варіант вказує на одне із зображень товару. Варіант, що використовує головне зображення, не завантажує його вдруге.',
'Shopify_G_Assigned' => 'призначається цьому варіанту',
'Shopify_G_Img_3' => 'Зображення, збережене як файл, {uploaded} в Shopify, а не передається посиланням, тож це працює навіть тоді, коли ця інсталяція недоступна з інтернету. Зображення, додане як вставлене посилання, передається в Shopify як цей URL, який має бути загальнодоступним.',
'Shopify_G_Uploaded' => 'завантажується',
'Shopify_G_Img_4' => 'Вони надсилаються повторно лише тоді, коли справді змінюються, — передавання, яке змінює лише ціну, не зачіпає зображення магазину, оскільки їх надсилання замінює весь набір.',
'Shopify_G_Img_5' => 'Видалення зображення в ERP {not} видаляє його в Shopify. Видаліть його й там, інакше магазин і далі його показуватиме.',
'Shopify_G_Commands' => 'Корисні команди',
'Shopify_G_Command_Copied' => 'Команду скопійовано',
'Shopify_G_Foot' => 'Кожна синхронізація записує в {logs}, а «Огляд» кожного магазину показує, коли кожен крок востаннє запускався, коли настане наступний і що його блокує, якщо щось блокує. Саме туди варто дивитися насамперед, коли синхронізація зробила не те, що ви очікували.',
'Shopify_G_Covers' => 'Охоплює',
'Shopify_G_Covers_Rt' => 'Замовлення та зміни, внесені в Shopify; запаси, що виходять з ERP (продаж POS, повернення, коригування)',
'Shopify_G_Covers_Sch' => 'Усе в обох напрямках — включно з передаванням каталогу та всім, що пропустив швидкий шлях',
'Shopify_G_Speed' => 'Швидкість',
'Shopify_G_Speed_Rt' => 'Секунди',
'Shopify_G_Speed_Sch' => 'Інтервал кроку (від 5 хвилин до 7 днів)',
'Shopify_G_Needs' => 'Потрібно',
'Shopify_G_Needs_Rt' => 'Публічна адреса HTTPS і секрет підпису для вхідних вебхуків. Для вихідних запасів нічого не потрібно',
