'Shopify_G_Tab_In_Edit' => 'Вкладка в «Редагувати магазин»',
'Shopify_G_Set_Credentials' => 'Client ID + secret або токен доступу, секрет підпису, версія API',
'Shopify_G_Set_Credentials_What' => 'Облікові дані із застосунку Shopify (Dev Dashboard або застарілий власний застосунок).',
'Shopify_G_Set_Targets' => 'Склад ERP, локація Shopify',
'Shopify_G_Set_Targets_What' => 'Які запаси продає цей магазин і куди записуються замовлення.',
'Shopify_G_Set_Price_What' => 'Роздрібна, оптова або мінімальна ціна.',
'Shopify_G_Set_Create_Missing' => 'Створювати відсутні товари / клієнтів',
'Shopify_G_Set_Create_Missing_What' => 'Чи може отримання створювати записи ERP, які не вдалося зіставити.',
'Shopify_G_Set_Entities' => 'Які сутності синхронізуються взагалі',
'Shopify_G_Set_Entities_What' => 'Вимкнено тут — означає вимкнено всюди: вручну, за розкладом і через вебхуки.',
'Shopify_G_Set_Scheduler_What' => 'Перемикач планувальника.',
'Shopify_G_Set_Push_What' => 'Миттєве передавання запасів, що ставиться в чергу під час продажу чи коригування.',
