'StoreAdm_Eg' => 'напр. {example}',
'StoreAdm_Stock_Required_Available' => '{name}: потрібно {need} — доступно {have}',
'StoreAdm_PG_Intro_Msg' => 'PayPal, Paystack, Flutterwave, Razorpay, bKash і SSLCommerz використовуються лише під час оформлення замовлення в ІНТЕРНЕТ-МАГАЗИНІ.',
'StoreAdm_PG_Intro_Desc' => 'Ключі Stripe спільні для всієї системи (панель адміністратора та інтернет-магазин використовують одну інтеграцію Stripe). Кожна вкладка вмикає або вимикає свій спосіб оплати для оформлення замовлення в інтернет-магазині; «Офлайн-платежі» містить способи, оплата якими здійснюється поза системою.',
'StoreAdm_PG_Used_By_Store_Only' => 'Використовується лише під час оформлення замовлення в інтернет-магазині',
'StoreAdm_PG_Gw_Key' => '{gw} Key',
'StoreAdm_PG_Gw_Secret' => '{gw} Secret',
'StoreAdm_PG_Cards_Off' => 'Оплату карткою вимкнено',
'StoreAdm_PG_Cards_Off_Desc' => 'Ваші ключі збережено — оформлення замовлення в інтернет-магазині просто перестане пропонувати оплату карткою, доки ви знову її не ввімкнете.',
'StoreAdm_PG_No_Stripe_Key' => 'Ключ Stripe не збережено',
'StoreAdm_PG_No_Stripe_Key_Desc' => 'Введіть ключ і секрет Stripe, щоб почати приймати оплату карткою в інтернет-магазині.',
'StoreAdm_PG_Gw_Client_Id' => '{gw} Client ID',
'StoreAdm_PG_Gw_Client_Secret' => '{gw} Client Secret',
'StoreAdm_PG_Sandbox' => 'Sandbox (тестовий режим)',
'StoreAdm_PG_Sandbox_Paypal_Hint' => 'УВІМК. використовує {sandbox} з обліковими даними sandbox; ВИМКНІТЬ, щоб списувати кошти з реальних рахунків на {live}.',
'StoreAdm_PG_Gw_Webhook_Id_Opt' => '{gw} Webhook ID (необов\'язково)',
'StoreAdm_PG_Paypal_Webhook_Hint' => 'Резервний механізм для платежів, переспрямування браузера яких так і не відбулося, а також для повернень/чарджбеків. Зареєструйте вебхук на {site}, що вказує на URL нижче (події: {events}), і вставте його Webhook ID сюди.',
'StoreAdm_PG_Webhook_Url' => 'URL вебхука:',
'StoreAdm_PG_Gw_Disabled' => '{gw} вимкнено',
'StoreAdm_PG_Paypal_Disabled_Desc' => 'Увімкніть PayPal і введіть Client ID і Secret свого REST-застосунку (з {site}), щоб клієнти могли платити через PayPal під час оформлення замовлення в інтернет-магазині.',
'StoreAdm_PG_Gw_Public_Key' => '{gw} Public Key',
'StoreAdm_PG_Gw_Secret_Key' => '{gw} Secret Key',
'StoreAdm_PG_Paystack_Test_Live' => 'Тестовий чи робочий режим визначається парою ключів: ключі {test} працюють у тестовому режимі, ключі {live} списують кошти з реальних карток — окремого перемикача sandbox немає.',
'StoreAdm_PG_Paystack_Webhook_Url' => 'URL вебхука (необов\'язковий резервний механізм — вкажіть його в Settings → API Keys & Webhooks на панелі Paystack; запити перевіряються HMAC з вашим секретним ключем):',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'Увімкніть Paystack і введіть свої Public і Secret ключі (з {site} → Settings → API Keys), щоб приймати картки, банківські перекази та мобільні гроші під час оформлення замовлення в інтернет-магазині.',
'StoreAdm_PG_Secret_Hash_Opt' => 'Secret Hash (вебхуки, необов\'язково)',
'StoreAdm_PG_Flutterwave_Hash_Hint' => 'Secret Hash, який ви задали в Settings → Webhooks на панелі Flutterwave; вхідні вебхуки відхиляються, якщо їхній заголовок {header} не збігається.',
'StoreAdm_PG_Flutterwave_Info' => 'Використовує Flutterwave v3 API з класичними ключами. Тестовий чи робочий режим визначається парою ключів ({keys} чи робочі ключі) — окремого перемикача sandbox немає. Валюта магазину має бути ввімкнена у вашому обліковому записі Flutterwave.',
'StoreAdm_PG_Flutterwave_Webhook_Url' => 'URL вебхука (необов\'язковий резервний механізм — вкажіть його разом із Secret Hash вище на панелі Flutterwave):',
'StoreAdm_PG_Flutterwave_Disabled_Desc' => 'Увімкніть Flutterwave і введіть свої v3 Public і Secret ключі (з {site} → Settings → API), щоб приймати картки, мобільні гроші та банківські перекази під час оформлення замовлення в інтернет-магазині.',
'StoreAdm_PG_Gw_Key_Id' => '{gw} Key ID',
'StoreAdm_PG_Gw_Key_Secret' => '{gw} Key Secret',
